examples.template:
MonarchDataGrid(
    {{label}},
    rows: invoices,
    columns: [
        MonarchDataGridColumn({{columns.0.header}}, id: {{columns.0.id}}, isHideable: false, pinned: .start, width: {{columns.0.width}}, value: { $0.number }),
        MonarchDataGridColumn(
            {{columns.1.header}},
            id: {{columns.1.id}},
            width: {{columns.1.width}},
            edit: MonarchDataGridEdit(
                isRequired: true,
                value: { .text($0.customer) },
                onCommit: { invoice, value in
                    guard case .text(let text) = value else { return }
                    update(invoice.id) { $0.customer = text }
                }
            ),
            value: { $0.customer }
        ),
        MonarchDataGridColumn(
            {{columns.2.header}},
            id: {{columns.2.id}},
            width: {{columns.2.width}},
            edit: MonarchDataGridEdit(
                kind: .select,
                options: Self.statuses.map { MonarchEditableCellOption($0, value: $0) },
                value: { .text($0.status) },
                onCommit: { invoice, value in
                    guard case .text(let text) = value else { return }
                    update(invoice.id) { $0.status = text }
                }
            ),
            value: { $0.status }
        ),
        MonarchDataGridColumn(
            {{columns.3.header}},
            id: {{columns.3.id}},
            isNumeric: true,
            width: {{columns.3.width}},
            edit: MonarchDataGridEdit(
                kind: .number,
                minimum: 0,
                value: { .number($0.amount) },
                onCommit: { invoice, value in
                    guard case .number(let amount) = value else { return }
                    update(invoice.id) { $0.amount = amount }
                }
            ),
            value: { String(format: "%.2f", $0.amount) }
        ),
        MonarchDataGridColumn({{columns.4.header}}, id: {{columns.4.id}}, width: {{columns.4.width}}, value: { $0.due }),
    ],
    sort: $sort,
    selection: $selection,
    layout: .table,
    rowActions: { invoice in
        [
            MonarchDataTableRowAction({{rowActions.0}}) {},
            MonarchDataTableRowAction({{rowActions.1}}, isDestructive: true) {
                invoices.removeAll { $0.id == invoice.id }
            },
        ]
    }
)
.frame(height: 900)

examples.setupTemplate:
struct Invoice: Identifiable, Sendable {
    let id: String
    let number: String
    var customer: String
    var status: String
    var amount: Double
    let due: String
}

private static let customers = [{{customers.0}}, {{customers.1}}, {{customers.2}}, {{customers.3}}]
private static let statuses = [{{statuses.0}}, {{statuses.1}}, {{statuses.2}}, {{statuses.3}}]
@State private var invoices: [Invoice] = (0..<{{rowCount}}).map { (i: Int) -> Invoice in
    Invoice(
        id: "inv-\(i)",
        number: "INV-" + String(format: "%05d", i + 1),
        customer: Self.customers[i % Self.customers.count],
        status: Self.statuses[i % Self.statuses.count],
        amount: Double((i * 7919) % 50_000) / 100,
        due: String(format: "2026-%02d-%02d", i % 12 + 1, i % 27 + 1)
    )
}
@State private var sort: MonarchDataTableSort?
@State private var selection: Set<String> = []

private func update(_ id: String, _ change: (inout Invoice) -> Void) {
    guard let index = invoices.firstIndex(where: { $0.id == id }) else { return }
    change(&invoices[index])
}

