examples.code:
MonarchDataGrid(
    "Contacts",
    rows: contacts,
    columns: [
        MonarchDataGridColumn("Name", value: { $0.name }),
        MonarchDataGridColumn(
            "Phone",
            edit: MonarchDataGridEdit(
                placeholder: "Add a phone number",
                value: { .text($0.phone) },
                onCommit: { contact, value in
                    if case .text(let text) = value { contacts[contact.id - 1].phone = text }
                }
            ),
            value: { $0.phone }
        ),
    ],
    layout: .list
)
.frame(height: 320)
